FuncDef.Code:
vec3 backdropAnimatedRings(in vec3 dir, in vec3 colorTop, in vec3 colorBottom, in float animOffset, in float animSpeed, in float freq, in float contrastMul, in float contrastPow)
{
    float sinArg = animOffset + iTime * animSpeed + freq * PI * dir.y;

    float param01 = 0.5 + 0.5 * sin(sinArg);

    vec3 color = mix(colorBottom, colorTop, param01);

    // light gradient from top to bottom
    color *= 0.5 * dir.y + 0.5;

    // contrast
    color *= contrastMul;
    color = pow(color, vec3(contrastPow));

    return color;
}
